replacements.after:
},[lang,kind]);
const barriers=kind==='barriers',titleId=barriers?'preview-barriers-title':'preview-benefits-title';
return <section className={'preview-benefits'+(barriers?' preview-barriers':'')} ref={root} aria-labelledby={titleId}><div className="preview-benefits-pin" ref={pin}><h2 id={titleId}>{c(barriers?p.barriersTitle:p.benefitsTitle)}</h2><div className="preview-benefits-window"><div className="preview-benefits-track" ref={track}>{(barriers?p.barriers:p.benefits).map((x,i)=><article key={x[0][0]}>{!barriers&&<span className="preview-benefit-number" aria-hidden="true">0{i+1}</span>}<h3>{c(x[0])}</h3><p>{barriers&&<span className="preview-solution-arrow" aria-hidden="true">→</span>}{c(x[1])}</p></article>)}</div></div>{!barriers&&<p className="preview-benefits-close"><strong>{c(p.benefitsClose)}</strong></p>}</div></section>;

/* Owner's mobile review: photography leads, colour replaces numbering. */
@media (max-width:899px) {
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-wants li { border:0; grid-template-columns:10px minmax(0,1fr); gap:18px; padding-block:13px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-wants li > span { font-size:0; padding:0; width:8px; height:8px; border-radius:50%; background:var(--m-accent); opacity:1; margin-top:12px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-wants li:nth-child(even) > span { background:var(--sandstone); }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-benefit-number { display:none; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-benefits:not(.preview-barriers) article { border-color:color-mix(in srgb,var(--m-accent) 48%,transparent); background:color-mix(in srgb,var(--m-accent) 8%,transparent); border-top:3px solid var(--m-accent); }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-benefits:not(.preview-barriers) article h3 { color:var(--m-accent); margin-top:0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-work .m-work-layout { grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr); gap:18px; align-items:start; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-work .m-handstand-composition { position:sticky; top:28px; width:100%; height:auto; grid-column:1; grid-row:1/3; align-self:start; margin-top:8px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-work .m-handstand { width:100%; margin:0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-work-text h2 { font-size:clamp(1.5rem,5vw,2rem); line-height:1.2; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-work .preview-comparison { grid-column:2; grid-row:2; margin:0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-work .preview-comparison-key { display:grid; gap:6px; margin-bottom:12px; font-size:.875rem; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-work .preview-comparison article { padding-block:18px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-work .preview-comparison article :is(p,h3) { grid-template-columns:13px minmax(0,1fr); gap:7px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-work .preview-comparison article p { font-size:.875rem; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-work .preview-comparison article h3 { font-size:1.125rem; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-comparison :is(h3,strong) > span,
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-comparison-key strong { color:var(--m-accent); }
 .tm-mobile[data-mobile-version][data-preview="v3"] #jak-to-funguje > .m-inner > .m-text-link { display:flex; width:fit-content; margin-top:28px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-about .m-about-composition { display:flow-root; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-about .m-prague { float:left; width:45%; height:auto; aspect-ratio:3/5; margin:0 20px 16px 0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-about .m-prague img { height:100%; object-fit:cover; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-about .m-about-heading { display:block; contain:none; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-about .m-about-heading .m-eyebrow { margin:0 0 8px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-about .m-about-heading h2 { font-size:1.35rem; margin:0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-about .m-about-heading .m-about-symbol { width:76px; height:62px; margin:12px 0 10px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-about-aside { margin:0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-about-aside p { margin:12px 0 0; font-size:.9375rem; line-height:1.6; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-contact .m-contact-actions { display:grid; grid-template-columns:minmax(0,1.25fr) minmax(0,1fr); align-items:stretch; gap:12px; width:100%; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-contact .m-contact-actions .m-contact-main { grid-column:1/-1; width:100%; padding:18px 12px; font-family:var(--ff-body); font-size:1.0625rem; letter-spacing:0; text-transform:none; font-weight:700; line-height:1.35; gap:10px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-contact .preview-cta-note { font-size:.8125rem; margin-top:7px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-contact .m-contact-actions .m-contact-mail { width:100%; min-width:0; padding:11px 7px; font-size:.75rem; letter-spacing:.02em; gap:6px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-contact .m-contact-actions .m-contact-mail svg { width:14px; height:14px; flex-shrink:0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-barriers { width:100%; margin:20px 0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-barriers h2 { font-size:1.5rem; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-barriers article h3 { margin-top:0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-barriers article p { display:grid; grid-template-columns:22px minmax(0,1fr); gap:10px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-solution-arrow { font-size:1.5rem; line-height:1.1; color:var(--m-accent); }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-collab-caption { padding-block:28px 0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-collab-caption p { font-family:var(--ff-display); font-size:1.4rem; line-height:1.4; margin:0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-collab-caption span { display:block; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-hero.preview-collaboration-hero .m-hero-photo img { top:48px; height:calc(100% - 48px); object-fit:cover; object-position:center top; }
}
